contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount, uint256 loanToCollateral) public {
        require(loanToCollateral != 0, "loanToCollateral != 0");

        uint256 reqID = c.requestLoan(amount, 0, loanToCollateral, 0); if (__ESBMC_reverted()) return;

        assert(reqID == 0);
    }

    receive() external payable {}
}

