pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 amount, uint256 loanToCollateral) internal {
        vm.assume(loanToCollateral != 0);
        uint256 reqID;
        try c.requestLoan(amount, 0, loanToCollateral, 0) returns (uint256 __r) { reqID = __r; } catch { return; }
        assertTrue(reqID == 0);
    }

    function testFuzz_run(uint256 amount, uint256 loanToCollateral) public {
        _run(amount, loanToCollateral);
    }

    receive() external payable {}
}
